{"command":"create","path":"/workspace/backend/db.go","file_text":"package main

import (
	"context"
	_ "embed"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

//go:embed schema.sql
var schemaSQL string

type DB struct {
	Pool  *pgxpool.Pool
	Mongo *mongo.Client
	Audit *mongo.Collection
}

func connectPostgres(ctx context.Context) (*pgxpool.Pool, error) {
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		url = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, err
	}
	cfg.MaxConns = 20
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return pool, nil
}

func connectMongo(ctx context.Context) (*mongo.Client, error) {
	uri := os.Getenv("MONGODB_URI")
	if uri == "" {
		uri = "mongodb://127.0.0.1:27017/arena"
	}
	client, err := mongo.Connect(options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	ctx2, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	if err := client.Ping(ctx2, nil); err != nil {
		return nil, err
	}
	return client, nil
}

func mongoDBName() string {
	uri := os.Getenv("MONGODB_URI")
	if uri == "" {
		return "arena"
	}
	// naive parse: last path segment
	for i := len(uri) - 1; i >= 0; i-- {
		if uri[i] == '/' {
			name := uri[i+1:]
			if name == "" {
				return "arena"
			}
			// strip query params
			for j := 0; j < len(name); j++ {
				if name[j] == '?' {
					return name[:j]
				}
			}
			return name
		}
	}
	return "arena"
}

func applyMigrations(ctx context.Context, pool *pgxpool.Pool) error {
	_, err := pool.Exec(ctx, schemaSQL)
	if err != nil {
		return fmt.Errorf("apply migrations: %w", err)
	}
	return nil
}

func ensureMongoIndexes(ctx context.Context, client *mongo.Client) (*mongo.Collection, error) {
	db := client.Database(mongoDBName())
	coll := db.Collection("audit_entries")

	names := []string{}
	cur, err := db.ListCollectionNames(ctx, map[string]interface{}{"name": "audit_entries"})
	if err == nil {
		names = cur
	}
	if len(names) == 0 {
		if err := db.CreateCollection(ctx, "audit_entries"); err != nil {
			log.Printf("createCollection audit_entries: %v", err)
		}
	}

	indexModels := []mongo.IndexModel{
		{Keys: map[string]interface{}{"occurredAt": -1}},
		{Keys: map[string]interface{}{"actorId": 1}},
		{Keys: map[string]interface{}{"entityType": 1, "entityId": 1}},
		{Keys: map[string]interface{}{"action": 1}},
		{Keys: map[string]interface{}{"role": 1}},
		{Keys: map[string]interface{}{"success": 1}},
		{Keys: map[string]interface{}{"searchText": "text"}},
	}
	_, err = coll.Indexes().CreateMany(ctx, indexModels)
	if err != nil {
		log.Printf("mongo index creation warning: %v", err)
	}
	return coll, nil
}
"}

{"command":"create","path":"/workspace/backend/httputil.go","file_text":"package main

import (
	"encoding/json"
	"net/http"
)

type apiError struct {
	Status int
	Code   string
	Msg    string
}

func (e *apiError) Error() string { return e.Msg }

func newErr(status int, code, msg string) *apiError {
	return &apiError{Status: status, Code: code, Msg: msg}
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, err error) {
	if ae, ok := err.(*apiError); ok {
		writeJSON(w, ae.Status, map[string]interface{}{"error": ae.Msg, "code": ae.Code})
		return
	}
	writeJSON(w, 500, map[string]interface{}{"error": "internal error", "code": "internal_error"})
}

func errInvalidJSON(msg string) *apiError    { return newErr(400, "invalid_json", msg) }
func errUnauthorized() *apiError             { return newErr(401, "unauthorized", "unauthorized") }
func errForbidden() *apiError                { return newErr(403, "forbidden", "forbidden") }
func errNotFound() *apiError                 { return newErr(404, "not_found", "not found") }
func errRoleNotSelected() *apiError          { return newErr(409, "role_not_selected", "no active role selected") }
func errIdempotencyRequired() *apiError      { return newErr(400, "idempotency_required", "idempotencyKey is required") }
func errIdempotencyConflict() *apiError      { return newErr(409, "idempotency_conflict", "idempotency key already used with a different request") }
func errConcurrentConflict() *apiError       { return newErr(409, "concurrent_conflict", "concurrent modification detected") }
func errInternal(msg string) *apiError       { return newErr(500, "internal_error", msg) }

func decodeJSONBody(r *http.Request, v interface{}) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return errInvalidJSON(err.Error())
	}
	return nil
}
"}

{"command":"create","path":"/workspace/backend/auth.go","file_text":"package main

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"
)

var jwtSecret []byte

func initJWTSecret() {
	s := os.Getenv("JWT_SECRET")
	if s == "" {
		s = "lab-sample-dev-secret-change-me"
	}
	jwtSecret = []byte(s)
}

func hashPassword(password string) string {
	salt := make([]byte, 16)
	_, _ = rand.Read(salt)
	saltHex := hex.EncodeToString(salt)
	h := sha256.Sum256([]byte(saltHex + ":" + password))
	return saltHex + ":" + hex.EncodeToString(h[:])
}

func verifyPassword(password, stored string) bool {
	var saltHex string
	for i := 0; i < len(stored); i++ {
		if stored[i] == ':' {
			saltHex = stored[:i]
			break
		}
	}
	if saltHex == "" {
		return false
	}
	h := sha256.Sum256([]byte(saltHex + ":" + password))
	expected := saltHex + ":" + hex.EncodeToString(h[:])
	return expected == stored
}

type sessionClaims struct {
	SessionID string `json:"sid"`
	UserID    string `json:"uid"`
	jwt.RegisteredClaims
}

func issueToken(sessionID, userID string) (string, error) {
	claims := sessionClaims{
		SessionID: sessionID,
		UserID:    userID,
		RegisteredClaims: jwt.RegisteredClaims{
			IssuedAt:  jwt.NewNumericDate(time.Now()),
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
		},
	}
	tok := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	return tok.SignedString(jwtSecret)
}

func parseToken(tokenStr string) (*sessionClaims, error) {
	claims := &sessionClaims{}
	_, err := jwt.ParseWithClaims(tokenStr, claims, func(t *jwt.Token) (interface{}, error) {
		return jwtSecret, nil
	})
	if err != nil {
		return nil, err
	}
	return claims, nil
}

type AuthedUser struct {
	UserID     string
	Username   string
	FullName   string
	Roles      []string
	Qualifications []string
	Active     bool
	AssignedLocationID string
	SessionID  string
	ActiveRole string
}

func (app *App) authenticate(ctx context.Context, tokenStr string) (*AuthedUser, error) {
	claims, err := parseToken(tokenStr)
	if err != nil {
		return nil, errUnauthorized()
	}
	row := app.DB.Pool.QueryRow(ctx, `
		SELECT s.id, s.active_role, s.revoked, u.id, u.username, u.full_name, u.roles, u.qualifications, u.active, COALESCE(u.assigned_location_id::text, '')
		FROM sessions s JOIN users u ON u.id = s.user_id
		WHERE s.id = $1`, claims.SessionID)
	var sessID, activeRole, uid, username, fullName, assignedLoc string
	var revoked, active bool
	var roles, quals []string
	if err := row.Scan(&sessID, &activeRole, &revoked, &uid, &username, &fullName, &roles, &quals, &active, &assignedLoc); err != nil {
		return nil, errUnauthorized()
	}
	if revoked || !active {
		return nil, errUnauthorized()
	}
	return &AuthedUser{
		UserID: uid, Username: username, FullName: fullName, Roles: roles, Qualifications: quals,
		Active: active, AssignedLocationID: assignedLoc, SessionID: sessID, ActiveRole: activeRole,
	}, nil
}

func newSession(ctx context.Context, app *App, userID string) (string, string, error) {
	id := uuid.New().String()
	_, err := app.DB.Pool.Exec(ctx, `INSERT INTO sessions (id, user_id, active_role) VALUES ($1,$2,NULL)`, id, userID)
	if err != nil {
		return "", "", err
	}
	tok, err := issueToken(id, userID)
	if err != nil {
		return "", "", err
	}
	return tok, id, nil
}

func hasRole(u *AuthedUser, role string) bool {
	for _, r := range u.Roles {
		if r == role {
			return true
		}
	}
	return false
}

func genRandomHex(n int) string {
	b := make([]byte, n)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func fmtErr(context string, err error) error {
	return fmt.Errorf("%s: %w", context, err)
}
"}

{"command":"create","path":"/workspace/backend/app.go","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"sync"
	"time"
)

type App struct {
	DB       *DB
	Mux      *http.ServeMux
	events   *EventBus
	svcMu    sync.Mutex
	svcCurrentVersion int
}

type ctxKey string

const ctxUserKey ctxKey = "authed_user"

func userFromCtx(ctx context.Context) *AuthedUser {
	v := ctx.Value(ctxUserKey)
	if v == nil {
		return nil
	}
	return v.(*AuthedUser)
}

// withAuth ensures a valid bearer [REDACTED]; does not require a role to be selected.
func (app *App) withAuth(next func(w http.ResponseWriter, r *http.Request, u *AuthedUser)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := extractBearer(r)
		if tok == "" {
			writeErr(w, errUnauthorized())
			return
		}
		u, err := app.authenticate(r.Context(), tok)
		if err != nil {
			writeErr(w, err)
			return
		}
		ctx := context.WithValue(r.Context(), ctxUserKey, u)
		next(w, r.WithContext(ctx), u)
	}
}

// withRole ensures auth + an active role is selected + (if roles given) the active role is one of them.
func (app *App) withRole(allowed []string, next func(w http.ResponseWriter, r *http.Request, u *AuthedUser)) http.HandlerFunc {
	return app.withAuth(func(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
		if u.ActiveRole == "" {
			writeErr(w, errRoleNotSelected())
			return
		}
		if len(allowed) > 0 {
			ok := false
			for _, a := range allowed {
				if a == u.ActiveRole {
					ok = true
					break
				}
			}
			if !ok {
				writeErr(w, errForbidden())
				return
			}
		}
		next(w, r, u)
	})
}

func extractBearer(r *http.Request) string {
	h := r.Header.Get("Authorization")
	const p = "Bearer "
	if len(h) > len(p) && h[:len(p)] == p {
		return h[len(p):]
	}
	return ""
}

func mustAtoi(s string, def int) int {
	n := 0
	neg := false
	if s == "" {
		return def
	}
	for i, c := range s {
		if i == 0 && c == '-' {
			neg = true
			continue
		}
		if c < '0' || c > '9' {
			return def
		}
		n = n*10 + int(c-'0')
	}
	if neg {
		n = -n
	}
	return n
}

func nowUTC() time.Time { return time.Now().UTC() }

func logf(format string, args ...interface{}) {
	log.Printf(format, args...)
}
"}

{"command":"create","path":"/workspace/backend/events.go","file_text":"package main

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// EventBus fans out newly created events to connected websocket subscribers.
type EventBus struct {
	mu   sync.Mutex
	subs map[chan RealtimeEvent]bool
}

func newEventBus() *EventBus {
	return &EventBus{subs: map[chan RealtimeEvent]bool{}}
}

func (b *EventBus) subscribe() chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 64)
	b.mu.Lock()
	b.subs[ch] = true
	b.mu.Unlock()
	return ch
}

func (b *EventBus) unsubscribe(ch chan RealtimeEvent) {
	b.mu.Lock()
	delete(b.subs, ch)
	b.mu.Unlock()
	close(ch)
}

func (b *EventBus) publish(ev RealtimeEvent) {
	b.mu.Lock()
	defer b.mu.Unlock()
	for ch := range b.subs {
		select {
		case ch <- ev:
		default:
		}
	}
}

// emitEvent persists an event to Postgres (durable, resumable) and publishes it to
// currently connected websocket subscribers. audienceRole/audienceUserID may be empty
// to indicate the event is visible to any authenticated connection.
func (app *App) emitEvent(ctx context.Context, evType, entityType, entityID string, payload map[string]interface{}, audienceRole, audienceUserID string) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	pb, _ := json.Marshal(payload)
	var id int64
	var createdAt time.Time
	err := app.DB.Pool.QueryRow(ctx, `
		INSERT INTO realtime_events (type, entity_type, entity_id, payload, audience_role, audience_user_id, created_at)
		VALUES ($1,$2,$3,$4,NULLIF($5,''),NULLIF($6,'')::uuid, now())
		RETURNING id, created_at`,
		evType, entityType, entityID, pb, audienceRole, audienceUserID).Scan(&id, &createdAt)
	if err != nil {
		logf("emitEvent insert failed: %v", err)
		return
	}
	ev := RealtimeEvent{ID: id, Type: evType, EntityType: entityType, EntityID: entityID, Payload: payload, CreatedAt: createdAt}
	app.events.publish(ev)
}

var wsUpgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
	Subprotocols: []string{"lab-logistics-v1"},
}

// handleEvents implements GET /api/events either as a WebSocket upgrade (subprotocol
// carries a base64url bearer.<token> auth) or, for simple polling clients, a plain
// JSON GET listing events since a cursor.
func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	// Determine auth: prefer the Sec-WebSocket-Protocol bearer, fallback to Authorization header.
	var tok string
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	if proto != "" {
		parts := strings.Split(proto, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(p, "bearer.") {
				encoded := strings.TrimPrefix(p, "bearer.")
				if decoded, err := base64.RawURLEncoding.DecodeString(encoded); err == nil {
					tok = string(decoded)
				} else {
					tok = encoded
				}
			}
		}
	}
	if tok == "" {
		tok = extractBearer(r)
	}
	u, err := app.authenticate(r.Context(), tok)
	if err != nil {
		writeErr(w, errUnauthorized())
		return
	}

	sinceStr := r.URL.Query().Get("since")
	since := int64(0)
	if sinceStr != "" {
		since, _ = strconv.ParseInt(sinceStr, 10, 64)
	}

	if websocket.IsWebSocketUpgrade(r) {
		app.serveWSEvents(w, r, u, since)
		return
	}

	// Plain HTTP polling fallback.
	events, cursor := app.fetchEventsSince(r.Context(), u, since, 500)
	writeData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
}

func (app *App) serveWSEvents(w http.ResponseWriter, r *http.Request, u *AuthedUser, since int64) {
	conn, err := wsUpgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	// Replay durable events since cursor first.
	events, cursor := app.fetchEventsSince(r.Context(), u, since, 1000)
	for _, ev := range events {
		if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
			return
		}
	}

	ch := app.events.subscribe()
	defer app.events.unsubscribe(ch)

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-done:
			return
		case ev := <-ch:
			if ev.ID <= cursor {
				continue
			}
			if !app.eventVisibleTo(ev, u) {
				continue
			}
			if err := conn.WriteJSON(map[string]interface{}{"event": ev}); err != nil {
				return
			}
			cursor = ev.ID
		case <-ticker.C:
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

func (app *App) eventVisibleTo(ev RealtimeEvent, u *AuthedUser) bool {
	return true
}

func (app *App) fetchEventsSince(ctx context.Context, u *AuthedUser, since int64, limit int) ([]RealtimeEvent, int64) {
	rows, err := app.DB.Pool.Query(ctx, `
		SELECT id, type, entity_type, entity_id, payload, created_at, COALESCE(audience_role,''), COALESCE(audience_user_id::text,'')
		FROM realtime_events
		WHERE id > $1
		  AND (audience_role IS NULL OR audience_role = $2)
		  AND (audience_user_id IS NULL OR audience_user_id = $3::uuid)
		ORDER BY id ASC LIMIT $4`, since, u.ActiveRole, u.UserID, limit)
	if err != nil {
		return []RealtimeEvent{}, since
	}
	defer rows.Close()
	out := []RealtimeEvent{}
	cursor := since
	for rows.Next() {
		var ev RealtimeEvent
		var payloadRaw []byte
		var audRole, audUser string
		if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payloadRaw, &ev.CreatedAt, &audRole, &audUser); err != nil {
			continue
		}
		_ = json.Unmarshal(payloadRaw, &ev.Payload)
		out = append(out, ev)
		if ev.ID > cursor {
			cursor = ev.ID
		}
	}
	return out, cursor
}
"}

{"command":"create","path":"/workspace/backend/audit.go","file_text":"package main

import (
	"context"
	"strings"
	"time"

	"github.com/google/uuid"
)

// recordAction writes a per-sample timeline row (Postgres, used for status timelines
// shown to owners/workers) and a searchable audit entry (MongoDB) in one call. Either
// sampleID or entityType/entityID may be used independent of each other.
func (app *App) recordAction(ctx context.Context, actorID, role, action, entityType, entityID string, sampleID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	now := nowUTC()

	if sampleID != "" {
		_, err := app.DB.Pool.Exec(ctx, `
			INSERT INTO sample_timeline (sample_id, action, actor_id, role, entity_type, entity_id, success, details, occurred_at)
			VALUES ($1,$2,NULLIF($3,'')::uuid,$4,$5,$6,$7,$8,$9)`,
			sampleID, action, actorID, role, entityType, entityID, success, toJSONB(details), now)
		if err != nil {
			logf("record timeline failed: %v", err)
		}
	}

	app.writeAuditMongo(ctx, actorID, role, action, entityType, entityID, success, details, now)
}

func (app *App) writeAuditMongo(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}, occurredAt time.Time) {
	if app.DB.Audit == nil {
		return
	}
	id := uuid.New().String()
	searchParts := []string{action, entityType, entityID, role, actorID}
	for k, v := range details {
		searchParts = append(searchParts, k)
		if s, ok := v.(string); ok {
			searchParts = append(searchParts, s)
		}
	}
	doc := map[string]interface{}{
		"auditId":    id,
		"audit_id":   id,
		"actorId":    actorID,
		"actor_id":   actorID,
		"role":       role,
		"actorRole":  role,
		"action":     action,
		"entityType": entityType,
		"entity_type": entityType,
		"entityId":   entityID,
		"entity_id":  entityID,
		"success":    success,
		"occurredAt": occurredAt,
		"occurred_at": occurredAt,
		"details":    details,
		"searchText": strings.Join(searchParts, " "),
	}
	_, err := app.DB.Audit.InsertOne(ctx, doc)
	if err != nil {
		logf("mongo audit insert failed: %v", err)
	}
}

func loadSampleTimeline(ctx context.Context, app *App, sampleID string) []TimelineEntry {
	rows, err := app.DB.Pool.Query(ctx, `
		SELECT id, action, COALESCE(actor_id::text,''), COALESCE(role,''), COALESCE(entity_type,''), COALESCE(entity_id,''), success, details, occurred_at
		FROM sample_timeline WHERE sample_id = $1 ORDER BY id ASC`, sampleID)
	out := []TimelineEntry{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var te TimelineEntry
		var details []byte
		if err := rows.Scan(&te.EventID, &te.Action, &te.ActorID, &te.Role, &te.EntityType, &te.EntityID, &te.Success, &details, &te.OccurredAt); err != nil {
			continue
		}
		te.Details = fromJSONB(details)
		out = append(out, te)
	}
	return out
}
"}

{"command":"create","path":"/workspace/backend/util.go","file_text":"package main

import (
	"encoding/json"
	"math"
)

func toJSONB(v interface{}) []byte {
	b, err := json.Marshal(v)
	if err != nil {
		return []byte("{}")
	}
	return b
}

func fromJSONB(b []byte) map[string]interface{} {
	out := map[string]interface{}{}
	if len(b) == 0 {
		return out
	}
	_ = json.Unmarshal(b, &out)
	return out
}

// haversineKm returns the great-circle distance between two coordinates in kilometers.
func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLon := (lon2 - lon1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func strInList(s string, list []string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func uniqStrings(in []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, s := range in {
		if s == "" || seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	return out
}
"}

{"command":"create","path":"/workspace/backend/planner.go","file_text":"package main

import (
	"container/heap"
	"context"
	"time"

	"github.com/jackc/pgx/v5"
)

type locNode struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	IsCollection    bool
	IsTransfer      bool
	IsHub           bool
	IsLab           bool
	CapacityUnits, ReservedUnits             int
	CooledCapacityUnits, CooledReservedUnits int
}

type edge struct {
	ID             string
	From, To       string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
	CapacityUnits, ReservedUnits             int
	CooledCapacityUnits, CooledReservedUnits int
}

type networkGraph struct {
	Nodes map[string]*locNode
	Edges []edge
	Adj   map[string][]int // location id -> edge indices
	LabAccepts map[string]map[string]bool // labID -> sampleTypeID -> accepts
}

func (app *App) loadNetworkGraph(ctx context.Context) (*networkGraph, error) {
	g := &networkGraph{Nodes: map[string]*locNode{}, Adj: map[string][]int{}, LabAccepts: map[string]map[string]bool{}}

	rows, err := app.DB.Pool.Query(ctx, `
		SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
		       is_collection_point, is_transfer_point, is_hub, is_laboratory,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		n := &locNode{}
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMinutes, &n.Active,
			&n.IsCollection, &n.IsTransfer, &n.IsHub, &n.IsLab,
			&n.CapacityUnits, &n.ReservedUnits, &n.CooledCapacityUnits, &n.CooledReservedUnits); err != nil {
			rows.Close()
			return nil, err
		}
		g.Nodes[n.ID] = n
	}
	rows.Close()

	erows, err := app.DB.Pool.Query(ctx, `
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections`)
	if err != nil {
		return nil, err
	}
	for erows.Next() {
		e := edge{}
		if err := erows.Scan(&e.ID, &e.From, &e.To, &e.TravelMinutes, &e.CostUnits, &e.Cooled, &e.Active,
			&e.CapacityUnits, &e.ReservedUnits, &e.CooledCapacityUnits, &e.CooledReservedUnits); err != nil {
			erows.Close()
			return nil, err
		}
		idx := len(g.Edges)
		g.Edges = append(g.Edges, e)
		g.Adj[e.From] = append(g.Adj[e.From], idx)
		// connections are usable in both directions for transport purposes
		g.Adj[e.To] = append(g.Adj[e.To], idx)
	}
	erows.Close()

	lrows, err := app.DB.Pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
	if err != nil {
		return nil, err
	}
	for lrows.Next() {
		var lab, st string
		var accepts bool
		if err := lrows.Scan(&lab, &st, &accepts); err != nil {
			continue
		}
		if g.LabAccepts[lab] == nil {
			g.LabAccepts[lab] = map[string]bool{}
		}
		g.LabAccepts[lab][st] = accepts
	}
	lrows.Close()

	return g, nil
}

// --- Dijkstra ---

type pqItem struct {
	loc      string
	dist     int
	pathEdge int // edge index used to arrive here (-1 for source)
	prevLoc  string
}

type priorityQueue []*pqItem

func (pq priorityQueue) Len() int            { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	it := old[n-1]
	*pq = old[:n-1]
	return it
}

type routeResult struct {
	PathLocations []string // ordered location ids, including entry and destination lab
	PathEdges     []string // connection ids used, len = len(PathLocations)-1
	TotalMinutes  int
	LabID         string
}

// findRoute runs Dijkstra from entryLocationID to the nearest active, accepting laboratory,
// honoring cooled-route requirements when requireCooled is true.
func findRoute(g *networkGraph, entryLocationID, sampleTypeID string, requireCooled bool) *routeResult {
	entry, ok := g.Nodes[entryLocationID]
	if !ok || !entry.Active {
		return nil
	}
	dist := map[string]int{entryLocationID: 0}
	prevEdge := map[string]int{}
	prevLoc := map[string]string{}
	visited := map[string]bool{}

	pq := &priorityQueue{{loc: entryLocationID, dist: 0, pathEdge: -1}}
	heap.Init(pq)

	// If entry itself is an accepting active lab, trivially return it.
	if entry.IsLab && g.LabAccepts[entryLocationID][sampleTypeID] {
		return &routeResult{PathLocations: []string{entryLocationID}, PathEdges: []string{}, TotalMinutes: 0, LabID: entryLocationID}
	}

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*pqItem)
		if visited[cur.loc] {
			continue
		}
		visited[cur.loc] = true

		node := g.Nodes[cur.loc]
		if node != nil && node.IsLab && g.LabAccepts[cur.loc][sampleTypeID] && cur.loc != entryLocationID {
			// reconstruct path
			pathLocs := []string{}
			pathEdges := []string{}
			loc := cur.loc
			for {
				pathLocs = append([]string{loc}, pathLocs...)
				pe, ok := prevEdge[loc]
				if !ok {
					break
				}
				pathEdges = append([]string{g.Edges[pe].ID}, pathEdges...)
				loc = prevLoc[loc]
				if loc == entryLocationID {
					pathLocs = append([]string{loc}, pathLocs...)
					break
				}
			}
			return &routeResult{PathLocations: pathLocs, PathEdges: pathEdges, TotalMinutes: cur.dist, LabID: cur.loc}
		}

		for _, ei := range g.Adj[cur.loc] {
			e := g.Edges[ei]
			if !e.Active {
				continue
			}
			if requireCooled && !e.Cooled {
				continue
			}
			var next string
			if e.From == cur.loc {
				next = e.To
			} else if e.To == cur.loc {
				next = e.From
			} else {
				continue
			}
			nn := g.Nodes[next]
			if nn == nil || !nn.Active {
				continue
			}
			nd := cur.dist + e.TravelMinutes
			if existing, ok := dist[next]; !ok || nd < existing {
				dist[next] = nd
				prevEdge[next] = ei
				prevLoc[next] = cur.loc
				heap.Push(pq, &pqItem{loc: next, dist: nd, pathEdge: ei, prevLoc: cur.loc})
			}
		}
	}
	return nil
}

// findEntryLocation resolves the collection entry point for a request origin.
func findEntryLocation(g *networkGraph, originType string, lat, lng float64, originNodeID string) *locNode {
	if originType == "node" && originNodeID != "" {
		n := g.Nodes[originNodeID]
		if n == nil || !n.Active {
			return nil
		}
		return n
	}
	var best *locNode
	bestDist := 1e18
	for _, n := range g.Nodes {
		if !n.Active || !n.IsCollection {
			continue
		}
		d := haversineKm(lat, lng, n.Lat, n.Lng)
		cov := n.CoverageKm
		if cov <= 0 || cov > 5 {
			cov = 5
		}
		if d <= cov && d < bestDist {
			bestDist = d
			best = n
		}
	}
	return best
}

// capacityCheck verifies that all nodes and edges in the given path have at least
// one available unit in the required pool (regular or cooled).
func capacityCheck(g *networkGraph, path []string, edges []string, cooled bool) bool {
	for _, locID := range path {
		n := g.Nodes[locID]
		if n == nil {
			return false
		}
		if cooled {
			if n.CooledCapacityUnits-n.CooledReservedUnits < 1 {
				return false
			}
		} else {
			if n.CapacityUnits-n.ReservedUnits < 1 {
				return false
			}
		}
	}
	for _, eid := range edges {
		for _, e := range g.Edges {
			if e.ID == eid {
				if cooled {
					if e.CooledCapacityUnits-e.CooledReservedUnits < 1 {
						return false
					}
				} else {
					if e.CapacityUnits-e.ReservedUnits < 1 {
						return false
					}
				}
			}
		}
	}
	return true
}

type planOutcome struct {
	Serviceable   bool
	Reason        string
	LabID         string
	EstimatedAt   time.Time
	PathLocations []string
	PathEdges     []string
	TotalMinutes  int
}

// planRoute computes a full serviceability+routing outcome without persisting anything.
func (app *App) planRoute(ctx context.Context, originType string, lat, lng float64, originNodeID string,
	sampleTypeID string, requireCooled bool, startAt time.Time, deadline time.Time) (*planOutcome, *networkGraph, error) {

	g, err := app.loadNetworkGraph(ctx)
	if err != nil {
		return nil, nil, err
	}

	entry := findEntryLocation(g, originType, lat, lng, originNodeID)
	if entry == nil {
		return &planOutcome{Serviceable: false, Reason: "outside_service_coverage"}, g, nil
	}

	route := findRoute(g, entry.ID, sampleTypeID, requireCooled)
	if route == nil {
		return &planOutcome{Serviceable: false, Reason: "no_accepting_laboratory"}, g, nil
	}

	if !capacityCheck(g, route.PathLocations, route.PathEdges, requireCooled) {
		return &planOutcome{Serviceable: false, Reason: "insufficient_capacity"}, g, nil
	}

	// Estimate arrival time by walking the path, accumulating handling + travel minutes.
	t := startAt
	t = t.Add(time.Duration(g.Nodes[route.PathLocations[0]].HandlingMinutes) * time.Minute)
	for i := 1; i < len(route.PathLocations); i++ {
		edgeID := route.PathEdges[i-1]
		var mins int
		for _, e := range g.Edges {
			if e.ID == edgeID {
				mins = e.TravelMinutes
				break
			}
		}
		t = t.Add(time.Duration(mins) * time.Minute)
		t = t.Add(time.Duration(g.Nodes[route.PathLocations[i]].HandlingMinutes) * time.Minute)
	}

	if t.After(deadline) {
		return &planOutcome{Serviceable: false, Reason: "deadline_unreachable", LabID: route.LabID, EstimatedAt: t,
			PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes}, g, nil
	}

	return &planOutcome{
		Serviceable: true, Reason: "serviceable", LabID: route.LabID, EstimatedAt: t,
		PathLocations: route.PathLocations, PathEdges: route.PathEdges, TotalMinutes: route.TotalMinutes,
	}, g, nil
}

// reserveCapacityForJourney reserves 1 unit (regular or cooled) at every node & edge in
// the path and records rows in capacity_reservations for later release.
func reserveCapacityForJourney(ctx context.Context, tx pgx.Tx, journeyID, sampleID string, path []string, edges []string, cooled bool) error {
	for _, locID := range path {
		col := "reserved_units"
		capCol := "capacity_units"
		if cooled {
			col = "cooled_reserved_units"
			capCol = "cooled_capacity_units"
		}
		res, err := tx.Exec(ctx, `UPDATE locations SET `+col+` = `+col+` + 1, updated_at=now()
			WHERE id = $1 AND `+col+` + 1 <= `+capCol, locID)
		if err != nil {
			return err
		}
		if res.RowsAffected() == 0 {
			return newErr(409, "capacity_exhausted", "capacity exhausted at location "+locID)
		}
		_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'location',$3,$4,1)`,
			sampleID, journeyID, locID, cooled)
		if err != nil {
			return err
		}
	}
	for _, eid := range edges {
		col := "reserved_units"
		capCol := "capacity_units"
		if cooled {
			col = "cooled_reserved_units"
			capCol = "cooled_capacity_units"
		}
		res, err := tx.Exec(ctx, `UPDATE connections SET `+col+` = `+col+` + 1, updated_at=now()
			WHERE id = $1 AND `+col+` + 1 <= `+capCol, eid)
		if err != nil {
			return err
		}
		if res.RowsAffected() == 0 {
			return newErr(409, "cooled_capacity_exhausted", "capacity exhausted on connection "+eid)
		}
		_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (sample_id, journey_id, pool_type, pool_id, cooled, units) VALUES ($1,$2,'connection',$3,$4,1)`,
			sampleID, journeyID, eid, cooled)
		if err != nil {
			return err
		}
	}
	return nil
}

// releaseJourneyCapacity releases all capacity reservations tied to a journey.
func releaseJourneyCapacity(ctx context.Context, tx pgx.Tx, journeyID string) error {
	rows, err := tx.Query(ctx, `SELECT id, pool_type, pool_id, cooled, units FROM capacity_reservations WHERE journey_id = $1 AND released = false`, journeyID)
	if err != nil {
		return err
	}
	type r struct {
		id       string
		poolType string
		poolID   string
		cooled   bool
		units    int
	}
	var list []r
	for rows.Next() {
		var it r
		if err := rows.Scan(&it.id, &it.poolType, &it.poolID, &it.cooled, &it.units); err != nil {
			rows.Close()
			return err
		}
		list = append(list, it)
	}
	rows.Close()

	for _, it := range list {
		col := "reserved_units"
		if it.cooled {
			col = "cooled_reserved_units"
		}
		table := "locations"
		if it.poolType == "connection" {
			table = "connections"
		}
		_, err := tx.Exec(ctx, `UPDATE `+table+` SET `+col+` = GREATEST(`+col+` - $1, 0), updated_at=now() WHERE id = $2`, it.units, it.poolID)
		if err != nil {
			return err
		}
		_, err = tx.Exec(ctx, `UPDATE capacity_reservations SET released = true, released_at = now() WHERE id = $1`, it.id)
		if err != nil {
			return err
		}
	}
	return nil
}
"}

