{"command":"create","path":"/workspace/backend/journey_builder.go","file_text":"package main

import (
	"context"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// buildJourneyForSample creates a journey + stops + assignments for a single sample
// following the planned route, reserves capacity, and offers the first assignment to
// an eligible worker. Returns the created journey id.
func (app *App) buildJourneyForSample(ctx context.Context, tx pgx.Tx, sample *sampleRow, outcome *planOutcome, g *networkGraph, requireCooled bool) (string, error) {
	journeyID := uuid.New().String()
	routeMode := "direct"
	if len(outcome.PathLocations) > 2 {
		routeMode = "multi_stop"
	}

	_, err := tx.Exec(ctx, `
		INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, valid)
		VALUES ($1,1,$2,'planned',$3,0,1,1,$4,true)`,
		journeyID, routeMode, outcome.EstimatedAt, []string{sample.ID})
	if err != nil {
		return "", err
	}

	// Stops: origin (pickup) + each path location (handoff) + final (delivery at lab)
	seq := 0
	t := sample.RequestedAt
	if sample.OriginType != "node" {
		// origin pseudo stop (not a network location) representing pickup point
	}
	// First stop: entry location (pickup completes collection)
	for i, locID := range outcome.PathLocations {
		stopType := "handoff"
		if i == 0 {
			stopType = "pickup"
		}
		if i == len(outcome.PathLocations)-1 {
			stopType = "delivery"
		}
		seq++
		stopID := uuid.New().String()
		n := g.Nodes[locID]
		_, err := tx.Exec(ctx, `
			INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, lat, lng)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
			stopID, journeyID, locID, stopType, seq, t, n.HandlingMinutes, n.Lat, n.Lng)
		if err != nil {
			return "", err
		}
		if i < len(outcome.PathEdges) {
			for _, e := range g.Edges {
				if e.ID == outcome.PathEdges[i] {
					t = t.Add(time.Duration(e.TravelMinutes) * time.Minute)
					break
				}
			}
		}
	}

	// Assignments
	seq = 0
	var nodeAssignmentIDs []string
	var laboratoryAssignmentIDs []string
	var firstTransport, middleTransport, finalTransport string
	var collectionAssignmentID string

	entryLoc := outcome.PathLocations[0]

	// Collection leg: origin -> entry location. Requires certified collection professional
	// unless the sample was already sealed (pre-sealed ingestion skips this).
	if !sample.AlreadySealed {
		seq++
		collectionAssignmentID = uuid.New().String()
		_, err := tx.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, kind, sequence, from_location_id, to_location_id, sample_id, status)
			VALUES ($1,$2,'collection',$3,NULL,$4,$5,'pending')`,
			collectionAssignmentID, journeyID, seq, entryLoc, sample.ID)
		if err != nil {
			return "", err
		}
	}

	for i := 0; i < len(outcome.PathLocations)-1; i++ {
		fromLoc := outcome.PathLocations[i]
		toLoc := outcome.PathLocations[i+1]
		edgeID := outcome.PathEdges[i]

		// Node assignment at fromLoc for intermediate stops (not the very first collection point
		// when this is the sample's first stop and there was no collection leg needed, and not
		// needed at the very first stop when a collection leg precedes it - node handler still
		// confirms incoming custody there when function is hub/transfer).
		fromNode := g.Nodes[fromLoc]
		if fromNode != nil && (fromNode.IsHub || fromNode.IsTransfer) {
			nodeAssignID := uuid.New().String()
			seq++
			var incoming, outgoing string
			if i == 0 {
				incoming = "" // collector delivers here
			} else {
				incoming = outcome.PathLocations[i-1]
			}
			outgoing = toLoc
			_, err := tx.Exec(ctx, `
				INSERT INTO assignments (id, journey_id, kind, sequence, node_id, sample_id, status, incoming_from_location_id, outgoing_to_location_id)
				VALUES ($1,$2,'node',$3,$4,$5,'pending',NULLIF($6,'')::uuid,$7)`,
				nodeAssignID, journeyID, seq, fromLoc, sample.ID, incoming, outgoing)
			if err != nil {
				return "", err
			}
			nodeAssignmentIDs = append(nodeAssignmentIDs, nodeAssignID)
		}

		transportID := uuid.New().String()
		seq++
		_, err := tx.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, kind, sequence, from_location_id, to_location_id, connection_id, sample_id, status)
			VALUES ($1,$2,'transport',$3,$4,$5,$6,$7,'pending')`,
			transportID, journeyID, seq, fromLoc, toLoc, edgeID, sample.ID)
		if err != nil {
			return "", err
		}
		if firstTransport == "" {
			firstTransport = transportID
		} else if i == len(outcome.PathLocations)-2 {
			finalTransport = transportID
		} else {
			middleTransport = transportID
		}
	}

	// Laboratory assignment at the destination lab.
	seq++
	labAssignID := uuid.New().String()
	_, err = tx.Exec(ctx, `
		INSERT INTO assignments (id, journey_id, kind, sequence, laboratory_id, expected_sample_type_id, sample_id, status)
		VALUES ($1,$2,'laboratory',$3,$4,$5,$6,'pending')`,
		labAssignID, journeyID, seq, outcome.LabID, sample.SampleTypeID, sample.ID)
	if err != nil {
		return "", err
	}
	laboratoryAssignmentIDs = append(laboratoryAssignmentIDs, labAssignID)

	_ = firstTransport
	_ = middleTransport
	_ = finalTransport
	_ = collectionAssignmentID
	_ = nodeAssignmentIDs
	_ = laboratoryAssignmentIDs

	// Reserve capacity for the path.
	if err := reserveCapacityForJourney(ctx, tx, journeyID, sample.ID, outcome.PathLocations, outcome.PathEdges, requireCooled); err != nil {
		return "", err
	}

	_, err = tx.Exec(ctx, `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2, updated_at=now() WHERE id=$3`,
		journeyID, outcome.LabID, sample.ID)
	if err != nil {
		return "", err
	}

	return journeyID, nil
}

type sampleRow struct {
	ID              string
	RequestID       string
	RequesterID     string
	OriginLat       float64
	OriginLng       float64
