import (
	"context"
	"log"
	"net/http"
	"os"
	"time"
)

func main() {
	initJWTSecret()

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	pool, err := connectPostgres(ctx)
	if err != nil {
		log.Fatalf("postgres connect: %v", err)
	}
	if err := applyMigrations(ctx, pool); err != nil {
		log.Fatalf("migrate: %v", err)
	}
	mongoClient, err := connectMongo(ctx)
	if err != nil {
		log.Fatalf("mongo connect: %v", err)
	}
	auditColl, err := ensureMongoIndexes(ctx, mongoClient)
	if err != nil {
		log.Fatalf("mongo indexes: %v", err)
	}
	cancel()

	db := &DB{Pool: pool, Mongo: mongoClient, Audit: auditColl}
	app := &App{DB: db, events: newEventBus()}

	if err := seedDefaults(context.Background(), app); err != nil {
		log.Fatalf("seed defaults: %v", err)
	}

	mux := http.NewServeMux()
	app.Mux = mux
	registerRoutes(app, mux)

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}

	go app.startBackgroundSweeper()

	srv := &http.Server{
		Addr:    addr,
		Handler: withCORS(mux),
	}
	log.Printf("listening on %s", addr)
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

func withCORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization,Content-Type,Sec-WebSocket-Protocol")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}
"}

{"command":"create","path":"/workspace/backend/seed.go","file_text":"package main

import (
	"context"
	"os"
)

// seedDefaults creates the first administrator (from ADMIN_USERNAME/ADMIN_PASSWORD)
// when no users exist yet, and ensures the four named default sample types exist.
// Both operations are idempotent so re-running start does not duplicate data.
func seedDefaults(ctx context.Context, app *App) error {
	var count int
	if err := app.DB.Pool.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count == 0 {
		username := os.Getenv("ADMIN_USERNAME")
		password := os.Getenv("ADMIN_PASSWORD")
		if username == "" {
			username = "admin"
		}
		if password == "" {
			password = "admin"
		}
		hash := hashPassword(password)
		_, err := app.DB.Pool.Exec(ctx, `
			INSERT INTO users (username, password_hash, full_name, roles, qualifications, certifications, active)
			VALUES ($1,$2,'Administrator', $3, '{}', '[]', true)
			ON CONFLICT (username) DO NOTHING`,
			username, hash, []string{RoleAdministrator})
		if err != nil {
			return err
		}
	}

	defaults := []struct {
		name       string
		namedRule  string
		cooled     bool
		batching   bool
		qualCode   string
	}{
		{"Amber", "amber", false, true, "amber_collector"},
		{"Indigo", "indigo", false, true, "indigo_collector"},
		{"Frost", "frost", true, true, "frost_collector"},
		{"Pulse", "pulse", false, false, "pulse_collector"},
	}
	for _, d := range defaults {
		_, err := app.DB.Pool.Exec(ctx, `
			INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
				temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed, named_rule)
			VALUES ($1, true, $2, 'standard_vial', 2, 8, $3, $4, $5)
			ON CONFLICT (name) DO NOTHING`,
			d.name, d.qualCode, d.cooled, d.batching, d.namedRule)
		if err != nil {
			return err
		}
	}

	// Indigo must not share a container with Amber: record as a mutual incompatibility.
	var amberID, indigoID string
	app.DB.Pool.QueryRow(ctx, `SELECT id FROM sample_types WHERE name='Amber'`).Scan(&amberID)
	app.DB.Pool.QueryRow(ctx, `SELECT id FROM sample_types WHERE name='Indigo'`).Scan(&indigoID)
	if amberID != "" && indigoID != "" {
		app.DB.Pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array(SELECT DISTINCT unnest(incompatible_sample_types || $2::uuid[])) WHERE id=$1`, amberID, []string{indigoID})
		app.DB.Pool.Exec(ctx, `UPDATE sample_types SET incompatible_sample_types = array(SELECT DISTINCT unnest(incompatible_sample_types || $2::uuid[])) WHERE id=$1`, indigoID, []string{amberID})
	}

	return nil
}
"}

{"command":"create","path":"/workspace/backend/idempotency.go","file_text":"package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
)

func hashRequest(v interface{}) string {
	b, _ := json.Marshal(v)
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

// idempotencyLookup returns (status, body, found). If a prior call with the same key
// and endpoint (scoped to the user) exists, its saved response is replayed verbatim.
// If the key was reused with a different request payload, ErrIdempotencyConflict is
// returned via the ok=false, conflict=true signal.
func idempotencyLookup(ctx context.Context, app *App, key, endpoint, userID, reqHash string) (int, map[string]interface{}, bool, bool) {
	if key == "" {
		return 0, nil, false, false
	}
	var status int
	var bodyRaw []byte
	var storedHash string
	err := app.DB.Pool.QueryRow(ctx, `
		SELECT response_status, response_body, request_hash FROM idempotency_keys
		WHERE key=$1 AND endpoint=$2 AND user_id=$3`, key, endpoint, userID).Scan(&status, &bodyRaw, &storedHash)
	if err != nil {
		return 0, nil, false, false
	}
	if storedHash != reqHash {
		return 0, nil, false, true
	}
	var body map[string]interface{}
	_ = json.Unmarshal(bodyRaw, &body)
	return status, body, true, false
}

func idempotencySave(ctx context.Context, app *App, key, endpoint, userID, reqHash string, status int, body interface{}) {
	if key == "" {
		return
	}
	b, _ := json.Marshal(body)
	_, _ = app.DB.Pool.Exec(ctx, `
		INSERT INTO idempotency_keys (key, endpoint, user_id, request_hash, response_status, response_body)
		VALUES ($1,$2,$3,$4,$5,$6)
		ON CONFLICT (key, endpoint, user_id) DO NOTHING`,
		key, endpoint, userID, reqHash, status, b)
}
"}

