        if m not in ('get','post'): continue
        out.append(f"=== {m.upper()} {p} [{op.get('operationId')}] ===")
        if 'parameters' in op and op['parameters']:
            out.append("PARAMS: " + json.dumps(op['parameters']))
        if 'requestBody' in op:
            schema = op['requestBody']['content']['application/json']['schema']
            out.append("REQUEST: " + json.dumps(schema))
        for status, resp in op.get('responses', {}).items():
            if 'content' in resp:
                schema = resp['content']['application/json']['schema']
                out.append(f"RESPONSE {status}: " + json.dumps(schema))
            else:
                out.append(f"RESPONSE {status}: (no content)")
        out.append("")
open('/tmp/full_ops.txt','w').write("\n".join(out))
print(len(out))
