}

func (app *App) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req authenticateUserReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Username == "" || req.Password == "" {
		writeErr(w, newErr(401, "invalid_credentials", "invalid credentials"))
		return
	}
	ctx := r.Context()
	var userID, hash string
	var roles []string
	var active bool
	err := app.DB.Pool.QueryRow(ctx, `SELECT id, password_hash, roles, active FROM users WHERE username=$1`, req.Username).
		Scan(&userID, &hash, &roles, &active)
	if err != nil || !active || !verifyPassword(req.Password, hash) {
		writeErr(w, newErr(401, "invalid_credentials", "invalid credentials"))
		return
	}

	tok, sessID, err := newSession(ctx, app, userID)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
		app.DB.Pool.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE id=$2`, activeRole, sessID)
	}

	app.recordAction(ctx, userID, activeRole, "sign_in", "user", userID, "", true, map[string]interface{}{"username": req.Username})

	writeData(w, 200, map[string]interface{}{
		"sessionToken": tok,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

type selectActiveRoleReq struct {
	Role string `json:"role"`
}

func (app *App) handleSelectActiveRole(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req selectActiveRoleReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if !isValidRole(req.Role) {
		writeErr(w, newErr(400, "invalid_role", "invalid role"))
		return
	}
	if !hasRole(u, req.Role) {
		writeErr(w, newErr(403, "role_not_held", "role not held by this account"))
		return
	}
	ctx := r.Context()
	_, err := app.DB.Pool.Exec(ctx, `UPDATE sessions SET active_role=$1, updated_at=now() WHERE id=$2`, req.Role, u.SessionID)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}
	app.recordAction(ctx, u.UserID, req.Role, "select_active_role", "user", u.UserID, "", true, map[string]interface{}{"role": req.Role})
	writeData(w, 200, map[string]interface{}{"activeRole": req.Role, "roles": u.Roles})
}

func (app *App) handleUIBootstrap(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodGet {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	ctx := r.Context()
	userOut := map[string]interface{}{
		"userId":                u.UserID,
		"username":              u.Username,
		"fullName":              u.FullName,
		"roles":                 u.Roles,
		"activeRole":            u.ActiveRole,
		"roleSelectionRequired": u.ActiveRole == "" && len(u.Roles) > 0,
	}
	out := map[string]interface{}{
		"user":       userOut,
		"serverTime": nowUTC().Format(time.RFC3339),
	}
	if u.ActiveRole == RoleRequester {
		rows, err := app.DB.Pool.Query(ctx, `
			SELECT id, status, sample_type_id, delivery_deadline, created_at
			FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`, u.UserID)
		samples := []map[string]interface{}{}
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status, stID string
				var deadline, createdAt time.Time
				if err := rows.Scan(&id, &status, &stID, &deadline, &createdAt); err == nil {
					samples = append(samples, map[string]interface{}{
						"sampleId": id, "status": status, "sampleTypeId": stID,
						"deliveryDeadline": deadline.Format(time.RFC3339), "createdAt": createdAt.Format(time.RFC3339),
					})
				}
			}
		}
		out["requesterSamples"] = samples
	}
	if u.ActiveRole == RoleDispatcher || u.ActiveRole == RoleAdministrator {
		ops, err := app.buildOperationsState(ctx, nil)
		if err == nil {
			out["operations"] = ops
		}
	}
	writeData(w, 200, out)
}
"}

