{"command":"create","path":"/workspace/backend/serviceability.go","file_text":"package main

import (
	"context"
)

// recomputeServiceabilitySnapshot computes a brand-new complete serviceability snapshot
// from the current network structure (active collection points, routes, laboratory
// capabilities, capacity) and atomically publishes it as the new current version.
// Because computation happens inside its own read of the DB and only the pointer flip
// at the end is visible, any reader concurrently calling read-serviceability-snapshot
// keeps seeing the previous complete version until this finishes.
func (app *App) recomputeServiceabilitySnapshot(ctx context.Context) error {
	app.svcMu.Lock()
	defer app.svcMu.Unlock()

	g, err := app.loadNetworkGraph(ctx)
	if err != nil {
		return err
	}

	regions := []ServiceabilityRegion{}
	activeCount := 0
	for _, n := range g.Nodes {
		if !n.Active || !n.IsCollection {
			continue
		}
		activeCount++
		cov := n.CoverageKm
		if cov <= 0 || cov > 5 {
			cov = 5
		}
		regions = append(regions, ServiceabilityRegion{
			LocationID: n.ID, Name: n.Name, Latitude: n.Lat, Longitude: n.Lng, CoverageKm: cov,
		})
	}

	var networkRevision int
	err = app.DB.Pool.QueryRow(ctx, `UPDATE network_state SET network_revision = network_revision + 1 WHERE id=1 RETURNING network_revision`).Scan(&networkRevision)
	if err != nil {
		return err
	}

	version := networkRevision
	_, err = app.DB.Pool.Exec(ctx, `
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete', now(), $2, $3, $4)
		ON CONFLICT (version) DO UPDATE SET status='complete', computed_at=now(), network_revision=$2, regions=$3, active_collection_point_count=$4`,
		version, networkRevision, toJSONB(regions), activeCount)
	if err != nil {
		return err
	}

	_, err = app.DB.Pool.Exec(ctx, `UPDATE network_state SET current_snapshot_version=$1 WHERE id=1`, version)
	return err
}

func (app *App) currentServiceabilitySnapshot(ctx context.Context) (map[string]interface{}, error) {
	var version int
	err := app.DB.Pool.QueryRow(ctx, `SELECT current_snapshot_version FROM network_state WHERE id=1`).Scan(&version)
	if err != nil {
		return nil, err
	}
	if version == 0 {
		// No snapshot published yet; compute one now so first reads are consistent.
		if err := app.recomputeServiceabilitySnapshot(ctx); err != nil {
			return nil, err
		}
		err = app.DB.Pool.QueryRow(ctx, `SELECT current_snapshot_version FROM network_state WHERE id=1`).Scan(&version)
		if err != nil {
			return nil, err
		}
	}
	var status string
	var computedAt interface{}
	var networkRevision, activeCount int
	var regionsRaw []byte
	row := app.DB.Pool.QueryRow(ctx, `
		SELECT status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots WHERE version=$1`, version)
	var computedAtStr string
	_ = computedAt
	if err := row.Scan(&status, &computedAtStr, &networkRevision, &regionsRaw, &activeCount); err != nil {
		return nil, err
	}
	var regions []ServiceabilityRegion
	_ = jsonUnmarshalSlice(regionsRaw, &regions)
	return map[string]interface{}{
		"version": version, "status": status, "computedAt": computedAtStr,
		"networkRevision": networkRevision, "regions": regions, "activeCollectionPointCount": activeCount,
	}, nil
}
"}

