	BatchingAllowed            *bool    `json:"batchingAllowed"`
}

func (app *App) handleCreateSampleType(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req createSampleTypeReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.Name == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeErr(w, newErr(400, "invalid_json", "name, containerType, temperatureMinC and temperatureMaxC are required"))
		return
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC {
		writeErr(w, newErr(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC"))
		return
	}
	qualRequired := false
	if req.QualifiedCollectorRequired != nil {
		qualRequired = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	incompat := req.IncompatibleSampleTypes
	if incompat == nil {
		incompat = []string{}
	}

	ctx := r.Context()
	var id string
	err := app.DB.Pool.QueryRow(ctx, `
		INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
		VALUES ($1,$2,NULLIF($3,''),$4,$5,$6,$7,$8,$9) RETURNING id`,
		req.Name, qualRequired, req.RequiredQualification, req.ContainerType,
		*req.TemperatureMinC, *req.TemperatureMaxC, incompat, cooled, batching,
	).Scan(&id)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}

	app.recordAction(ctx, u.UserID, u.ActiveRole, "create_sample_type", "sample_type", id, "", true, map[string]interface{}{"name": req.Name})

	writeData(w, 201, map[string]interface{}{
		"sampleTypeId": id, "name": req.Name, "qualifiedCollectorRequired": qualRequired,
		"requiredQualification": req.RequiredQualification, "containerType": req.ContainerType,
		"temperatureMinC": *req.TemperatureMinC, "temperatureMaxC": *req.TemperatureMaxC,
		"incompatibleSampleTypes": incompat, "requiresCooledRoute": cooled, "batchingAllowed": batching,
	})
}

