		return
	}
	var req updateSampleTypeReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.SampleTypeID == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeErr(w, newErr(400, "invalid_json", "sampleTypeId, containerType, temperatureMinC and temperatureMaxC are required"))
		return
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC {
		writeErr(w, newErr(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC"))
		return
	}
	ctx := r.Context()
	var exists bool
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM sample_types WHERE id=$1`, req.SampleTypeID).Scan(&exists)
	if !exists {
		writeErr(w, errNotFound())
		return
	}

	qualRequired := false
	if req.QualifiedCollectorRequired != nil {
		qualRequired = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batching := true
	if req.BatchingAllowed != nil {
		batching = *req.BatchingAllowed
	}
	incompat := req.IncompatibleSampleTypes
	if incompat == nil {
		incompat = []string{}
	}
	var requiredQual interface{}
	if req.RequiredQualification != nil && *req.RequiredQualification != "" {
		requiredQual = *req.RequiredQualification
	}

	var name string
	err := app.DB.Pool.QueryRow(ctx, `
		UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
			temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6, requires_cooled_route=$7,
			batching_allowed=$8, updated_at=now()
		WHERE id=$9 RETURNING name`,
		qualRequired, requiredQual, req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC,
		incompat, cooled, batching, req.SampleTypeID).Scan(&name)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}

	app.recordAction(ctx, u.UserID, u.ActiveRole, "update_sample_type", "sample_type", req.SampleTypeID, "", true, map[string]interface{}{"name": name})

	writeData(w, 201, map[string]interface{}{
		"sampleTypeId": req.SampleTypeID, "name": name, "qualifiedCollectorRequired": qualRequired,
		"requiredQualification": req.RequiredQualification, "containerType": req.ContainerType,
		"temperatureMinC": *req.TemperatureMinC, "temperatureMaxC": *req.TemperatureMaxC,
		"incompatibleSampleTypes": incompat, "requiresCooledRoute": cooled, "batchingAllowed": batching,
	})
}

func loadSampleTypeRow(ctx context.Context, app *App, id string) (containerType string, tMin, tMax float64, requiresCooled bool, incompatible []string, qualRequired bool, requiredQual string, batching bool, namedRule string, found bool) {
	err := app.DB.Pool.QueryRow(ctx, `
		SELECT container_type, temperature_min_c, temperature_max_c, requires_cooled_route,
		       incompatible_sample_types, qualified_collector_required, COALESCE(required_qualification,''),
		       batching_allowed, COALESCE(named_rule,'')
		FROM sample_types WHERE id=$1`, id).
		Scan(&containerType, &tMin, &tMax, &requiresCooled, &incompatible, &qualRequired, &requiredQual, &batching, &namedRule)
	if err != nil {
		return "", 0, 0, false, nil, false, "", false, "", false
	}
	return containerType, tMin, tMax, requiresCooled, incompatible, qualRequired, requiredQual, batching, namedRule, true
}
"}

