	CostUnits      *float64 `json:"costUnits"`
	Cooled         *bool    `json:"cooled"`
	Active         *bool    `json:"active"`
}

func (app *App) handleCreateConnection(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req createConnectionReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		writeErr(w, newErr(400, "invalid_connection", "fromLocationId, toLocationId, travelMinutes, costUnits and active are required"))
		return
	}
	if *req.TravelMinutes < 1 || *req.CostUnits < 0 {
		writeErr(w, newErr(400, "invalid_connection", "travelMinutes must be >= 1 and costUnits must be >= 0"))
		return
	}
	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}
	ctx := r.Context()

	var fromExists, toExists bool
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1`, req.FromLocationID).Scan(&fromExists)
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1`, req.ToLocationID).Scan(&toExists)
	if !fromExists || !toExists {
		writeErr(w, newErr(400, "invalid_connection", "fromLocationId and toLocationId must reference existing locations"))
		return
	}

	var id string
	err := app.DB.Pool.QueryRow(ctx, `
		INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6) RETURNING id`,
		req.FromLocationID, req.ToLocationID, *req.TravelMinutes, *req.CostUnits, cooled, *req.Active,
	).Scan(&id)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}

	app.recordAction(ctx, u.UserID, u.ActiveRole, "create_connection", "connection", id, "", true,
		map[string]interface{}{"fromLocationId": req.FromLocationID, "toLocationId": req.ToLocationID})
	app.recomputeServiceabilitySnapshot(ctx)

	writeData(w, 201, map[string]interface{}{
		"connectionId": id, "fromLocationId": req.FromLocationID, "toLocationId": req.ToLocationID,
		"travelMinutes": *req.TravelMinutes, "costUnits": *req.CostUnits, "cooled": cooled, "active": *req.Active,
	})
}

