{"command":"create","path":"/workspace/backend/handlers_capacity.go","file_text":"package main

import (
	"net/http"
)

type configureCapacityReq struct {
	ResourceID           string `json:"resourceId"`
	CapacityUnits        *int   `json:"capacityUnits"`
	CooledCapacityUnits  *int   `json:"cooledCapacityUnits"`
}

// handleConfigureCapacity configures regular/cooled capacity for a location (node or
// laboratory) or a transport connection. Administrators may configure any resource;
// node handlers and laboratory intake operators may only configure the single location
// they are assigned to.
func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req configureCapacityReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.ResourceID == "" || req.CapacityUnits == nil {
		writeErr(w, newErr(400, "invalid_capacity", "resourceId and capacityUnits are required"))
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if *req.CapacityUnits < 0 || cooled < 0 {
		writeErr(w, newErr(400, "invalid_capacity", "capacity values must be >= 0"))
		return
	}
	ctx := r.Context()

	var isLocation bool
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1`, req.ResourceID).Scan(&isLocation)

	table := "locations"
	if !isLocation {
		var isConn bool
		app.DB.Pool.QueryRow(ctx, `SELECT true FROM connections WHERE id=$1`, req.ResourceID).Scan(&isConn)
		if !isConn {
			writeErr(w, errNotFound())
			return
		}
		table = "connections"
	}

	if (u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam) && table == "locations" {
		if u.AssignedLocationID != req.ResourceID {
			writeErr(w, errForbidden())
			return
		}
	} else if u.ActiveRole == RoleNodeHandler || u.ActiveRole == RoleLaboratoryTeam {
		writeErr(w, errForbidden())
		return
	}

	var reserved, cooledReserved int
	app.DB.Pool.QueryRow(ctx, `SELECT reserved_units, cooled_reserved_units FROM `+table+` WHERE id=$1`, req.ResourceID).Scan(&reserved, &cooledReserved)
	if *req.CapacityUnits < reserved || cooled < cooledReserved {
		writeErr(w, newErr(409, "capacity_reserved", "capacity cannot be reduced below currently reserved units"))
		return
	}

	_, err := app.DB.Pool.Exec(ctx, `UPDATE `+table+` SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3`,
		*req.CapacityUnits, cooled, req.ResourceID)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}

	app.recordAction(ctx, u.UserID, u.ActiveRole, "configure_capacity", table, req.ResourceID, "", true,
		map[string]interface{}{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
	if table == "locations" {
		app.recomputeServiceabilitySnapshot(ctx)
	}

	writeData(w, 200, map[string]interface{}{
		"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
}

type configureLaboratoryAcceptanceReq struct {
	LaboratoryID string `json:"laboratoryId"`
	SampleTypeID string `json:"sampleTypeId"`
	Accepts      *bool  `json:"accepts"`
}

func (app *App) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request, u *AuthedUser) {
	if r.Method != http.MethodPost {
		writeErr(w, newErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	var req configureLaboratoryAcceptanceReq
	if err := decodeJSONBody(r, &req); err != nil {
		writeErr(w, err)
		return
	}
	if req.LaboratoryID == "" || req.SampleTypeID == "" || req.Accepts == nil {
		writeErr(w, newErr(400, "invalid_acceptance", "laboratoryId, sampleTypeId and accepts are required"))
		return
	}
	ctx := r.Context()

	var labExists, stExists bool
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM locations WHERE id=$1 AND is_laboratory`, req.LaboratoryID).Scan(&labExists)
	app.DB.Pool.QueryRow(ctx, `SELECT true FROM sample_types WHERE id=$1`, req.SampleTypeID).Scan(&stExists)
	if !labExists || !stExists {
		writeErr(w, newErr(400, "invalid_acceptance", "laboratoryId must be an active laboratory location and sampleTypeId must exist"))
		return
	}

	_, err := app.DB.Pool.Exec(ctx, `
		INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts)
		VALUES ($1,$2,$3)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$3`,
		req.LaboratoryID, req.SampleTypeID, *req.Accepts)
	if err != nil {
		writeErr(w, errInternal(err.Error()))
		return
	}

	app.recordAction(ctx, u.UserID, u.ActiveRole, "configure_laboratory_acceptance", "laboratory", req.LaboratoryID, "", true,
		map[string]interface{}{"sampleTypeId": req.SampleTypeID, "accepts": *req.Accepts})
	app.recomputeServiceabilitySnapshot(ctx)

	writeData(w, 200, map[string]interface{}{
		"acceptanceId": req.LaboratoryID + ":" + req.SampleTypeID, "accepts": *req.Accepts,
	})
}
"}

