                success[code]=sch
            else:
                # just grab error codes list
                try:
                    errs[code]=sch['properties']['code']['enum']
                except Exception:
                    errs[code]=sch
        entry['success']=success
        entry['errors']=errs
        out.append(entry)
json.dump(out, open('/tmp/allops.json','w'), indent=2)
print(len(out))
